"""Compute calibrated solar energy for the UTC day 2024-03-15."""

from __future__ import annotations

import json
import math
import re
from datetime import datetime
from pathlib import Path

import pandas as pd


DATA = Path("/app/dataset")
START = pd.Timestamp("2024-03-15 00:00:00", tz="UTC")
END = pd.Timestamp("2024-03-16 00:00:00", tz="UTC")
BTU_TO_KWH = 1055.05585262 / 3_600_000


def parse_timestamp(value: str) -> datetime | pd.NaT:
    value = value.strip()
    if re.fullmatch(r"\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}", value):
        fmt = "%Y-%m-%d %H:%M:%S"
    elif re.fullmatch(r"\d{2}\.\d{2}\.\d{4} \d{2}:\d{2}:\d{2}", value):
        fmt = "%d.%m.%Y %H:%M:%S"
    else:
        return pd.NaT
    try:
        return datetime.strptime(value, fmt)
    except ValueError:
        return pd.NaT


def parse_number(value: str) -> float:
    value = value.strip()
    if "," in value:
        value = value.replace(".", "").replace(",", ".")
    try:
        return float(value)
    except ValueError:
        return math.nan


def read_production(farm_id: str) -> pd.DataFrame:
    path = DATA / f"production_{farm_id}.csv"
    raw = path.read_bytes()
    encoding = "utf-16" if raw.startswith((b"\xff\xfe", b"\xfe\xff")) else "utf-8-sig"
    delimiter = ";" if ";" in raw.decode(encoding).splitlines()[3] else ","
    return pd.read_csv(
        path, encoding=encoding, sep=delimiter, skiprows=3,
        dtype=str, keep_default_na=False,
    )


def answer() -> dict[str, int]:
    farms = pd.read_csv(DATA / "farms.csv", dtype=str)
    registry = pd.read_csv(DATA / "farm_registry.csv", dtype=str)
    farms["name_key"] = farms["farm_name"].str.strip().str.casefold()
    registry["name_key"] = registry["farm_name"].str.strip().str.casefold()
    fleet = farms.merge(registry[["name_key", "farm_id"]], on="name_key", validate="one_to_one")

    with (DATA / "sensors_calibration.json").open() as f:
        configs = json.load(f)["enterprise_platform"]["deployment_environments"]["system_config"]["farms"]

    # Both windows were completed; the March 15 Sakura inspection was cancelled.
    maintenance = {
        "FARM_C": [("2024-03-16 08:00:00", "2024-03-16 12:00:00")],
        "FARM_F": [("2024-03-15 12:00:00", "2024-03-15 14:00:00")],
    }

    totals: dict[str, int] = {}
    for row in fleet.itertuples(index=False):
        farm_id = row.farm_id
        config = configs[farm_id]
        calibration = config["calibration_data"]
        sensor = config["sensor_info"]
        frame = read_production(farm_id)
        frame["local_timestamp"] = frame.iloc[:, 0].map(parse_timestamp)
        frame = frame.dropna(subset=["local_timestamp"])
        # The later duplicate is the corrected export of that timestamp.
        frame = frame.drop_duplicates(subset=["local_timestamp"], keep="last").copy()

        frame["utc_timestamp"] = frame["local_timestamp"].dt.tz_localize(
            row.timezone, ambiguous="raise", nonexistent="raise"
        ).dt.tz_convert("UTC")
        frame["temperature"] = frame["inverter_temperature_C"].map(parse_number)
        frame["true_value"] = (
            frame[calibration["value_column_name"]].map(parse_number)
            - float(calibration["calibration_offset"])
        )

        excluded = pd.Series(False, index=frame.index)
        for spike in frame.loc[frame["temperature"] > 85.0, "utc_timestamp"]:
            excluded |= (frame["utc_timestamp"] > spike) & (
                frame["utc_timestamp"] <= spike + pd.Timedelta(minutes=45)
            )
        for local_start, local_end in maintenance.get(farm_id, []):
            excluded |= frame["local_timestamp"].between(
                pd.Timestamp(local_start), pd.Timestamp(local_end), inclusive="left"
            )

        valid = frame.loc[
            (frame["utc_timestamp"] >= START)
            & (frame["utc_timestamp"] < END)
            & (~excluded)
            & (frame["true_value"] >= 0)
            & frame["true_value"].map(math.isfinite)
        ]
        unit = sensor["unit"].lower()
        if sensor["reading_type"] == "power":
            spacing = frame["local_timestamp"].sort_values().diff().dropna().mode().iloc[0]
            multiplier = spacing.total_seconds() / 3600
        elif unit == "kwh":
            multiplier = 1.0
        elif unit == "mwh":
            multiplier = 1000.0
        elif unit == "wh":
            multiplier = 0.001
        elif unit == "btu":
            multiplier = BTU_TO_KWH
        else:
            raise ValueError(f"Unexpected unit for {farm_id}: {unit}")
        totals[farm_id] = round(math.fsum(valid["true_value"] * multiplier))

    return totals


if __name__ == "__main__":
    with open("/app/answer.json", "w") as f:
        json.dump(answer(), f, default=list)

